package io.github.samblakeman.retrotv;

import android.content.Context;
import android.graphics.RectF;

import org.json.JSONArray;
import org.json.JSONObject;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One TV bezel set as generated by tools/make_bezels.py (params.json): wide art (landscape),
 * square art (foldable inner screen / tablet) and optional tall art (portrait pocket TV).
 */
final class BezelSet {
    /** Aspect ratio threshold above which wide landscape bezel art is used. */
    static final float SWITCH_AR = 1.6f;
    /** Outputs narrower than this (portrait phone screens) use the tall pocket-TV art. */
    static final float TALL_AR = 0.7f;

    static final class Layout {
        final String file;
        final float[] hole, body;
        final float ar;
        /** Per-layout CRT effect overrides (NaN = use the set's value). */
        final float scan, curve, vignette;

        Layout(JSONObject o) throws Exception {
            file = o.getString("file");
            hole = floats(o.getJSONArray("hole"));
            body = floats(o.getJSONArray("body"));
            ar = (float) o.getDouble("ar");
            JSONObject fx = o.optJSONObject("fx");
            scan = fx == null ? Float.NaN : (float) fx.optDouble("scan", Double.NaN);
            curve = fx == null ? Float.NaN : (float) fx.optDouble("curve", Double.NaN);
            vignette = fx == null ? Float.NaN : (float) fx.optDouble("vignette", Double.NaN);
            JSONObject ct = o.optJSONObject("controls");
            if (ct != null) {
                for (java.util.Iterator<String> it = ct.keys(); it.hasNext(); ) {
                    String k = it.next();
                    controls.put(k, floats(ct.getJSONArray(k)));
                }
            }
        }

        /** Touchable parts of the drawn case ("tune", "volume", buttons), normalised like the hole. */
        final Map<String, float[]> controls = new LinkedHashMap<>();

        /** Screen rectangle of the picture hole for an output of w x h (mirrors the shader). */
        RectF hole(float w, float h) { return toScreen(hole, w, h); }

        /** Screen rectangle of a control, or null if this art doesn't have it. */
        RectF control(String name, float w, float h) {
            float[] r = controls.get(name);
            return r == null ? null : toScreen(r, w, h);
        }

        private RectF toScreen(float[] r, float w, float h) {
            float bx = body[0] * ar, by = body[1], bw = body[2] * ar, bh = body[3];
            float s = Math.min(w / bw, h / bh);
            float offX = w * 0.5f - (bx + bw * 0.5f) * s;
            float spareY = h - bh * s;
            float alignY = h > w * 1.02f ? 0f : 0.5f;
            float offY = spareY * alignY - by * s;
            float x0 = offX + r[0] * ar * s, y0 = offY + r[1] * s;
            return new RectF(x0, y0, x0 + r[2] * ar * s, y0 + r[3] * s);
        }
    }

    final String name;
    final Layout wide, square, tall;   // tall may be null
    final float scan, lines, curve, vignette;

    private BezelSet(String name, JSONObject o) throws Exception {
        this.name = name;
        wide = new Layout(o.getJSONObject("wide"));
        square = new Layout(o.getJSONObject("square"));
        tall = o.has("tall") ? new Layout(o.getJSONObject("tall")) : null;
        JSONObject fx = o.getJSONObject("fx");
        scan = (float) fx.optDouble("scan", 0);
        lines = (float) fx.optDouble("lines", 0);
        curve = (float) fx.optDouble("curve", 0);
        vignette = (float) fx.optDouble("vignette", 0);
    }

    Layout layoutFor(float w, float h) {
        float r = w / h;
        if (r >= SWITCH_AR) return wide;
        if (tall != null && r < TALL_AR) return tall;
        return square;
    }

    float scan(Layout l) { return Float.isNaN(l.scan) ? scan : l.scan; }
    float curve(Layout l) { return Float.isNaN(l.curve) ? curve : l.curve; }
    float vignette(Layout l) { return Float.isNaN(l.vignette) ? vignette : l.vignette; }

    float bright(Layout l) {
        return 1f + 0.5f * scan(l) * 0.3f;
    }

    static Map<String, BezelSet> loadAll(Context c) {
        Map<String, BezelSet> m = new LinkedHashMap<>();
        try (InputStream in = c.getAssets().open("bezels/params.json")) {
            ByteArrayOutputStream bo = new ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            int n;
            while ((n = in.read(buf)) > 0) bo.write(buf, 0, n);
            JSONObject o = new JSONObject(bo.toString(StandardCharsets.UTF_8.name()));
            for (String k : new String[]{"tvwide", "tvcrt"}) m.put(k, new BezelSet(k, o.getJSONObject(k)));
        } catch (Exception e) {
            throw new RuntimeException("Bad bezel params", e);
        }
        return m;
    }

    private static float[] floats(JSONArray a) throws Exception {
        float[] f = new float[a.length()];
        for (int i = 0; i < f.length; i++) f[i] = (float) a.getDouble(i);
        return f;
    }
}
